<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; requireLogin();
$uid=isAdmin()?(int)($_GET['user']??$_POST['user_id']??currentUserId()):currentUserId();
$u=getUser($pdo,$uid); if(!$u||($u['status']??'')!=='active'||(!isAdmin()&&$uid!==currentUserId())){http_response_code(403);exit('Usuário inválido ou acesso negado.');}
$c=get4gConfig($pdo,$uid);
$colors=['cor_borda_campo'=>'CorBordaCampo','cor_icone_usuario'=>'CorIconeUsuario','cor_icone_senha'=>'CorIconeSenha','cor_botao_start'=>'CorBotaoStart','cor_borda_botao_start'=>'CorBordaBotaoStart','cor_fonte_botao_start'=>'CorFonteBotaoStart','cor_titulo_app'=>'CorTituloApp','cor_status'=>'CorStatus','cor_texto_versao'=>'CorTextoVersao','cor_numero_versao'=>'CorNumeroVersao','cor_ip'=>'CorIP','cor_operadora'=>'CorOperadora','cor_icone_atualizar'=>'CorIconeAtualizar'];
if($_SERVER['REQUEST_METHOD']==='POST'){
  $post=fn($k,$d='')=>trim((string)($_POST[$k]??$d));
  $ports=[]; foreach(preg_split('/[;,#,\s]+/',$post('udp_ports','7300;7400;7500'),-1,PREG_SPLIT_NO_EMPTY)?:[] as $p){if(ctype_digit($p)&&$p>=1&&$p<=65535)$ports[]=(string)(int)$p;}
  $d=['version'=>$post('version','0'),'app_name'=>$post('app_name','CYBERCOARI'),'release_notes'=>($_POST['release_notes']??''),'update_url'=>$post('update_url'),'sms_url'=>$post('sms_url'),'logoonline'=>$post('logoonline'),'fundoonline'=>$post('fundoonline'),'logonline'=>$post('logonline'),'rodapeonline'=>$post('rodapeonline'),'email_feedback'=>$post('email_feedback'),'contato'=>$post('contato'),'termos'=>$post('termos'),'check_user'=>$post('check_user','true'),'espessura_borda_campo'=>(int)$post('espessura_borda_campo','0'),'udp_ports'=>implode(';',array_values(array_unique($ports)))];
  foreach($colors as $col=>$label)$d[$col]=$post($col,(string)($c[$col]??''));
  if(save4gConfig($pdo,$uid,$d)){logActivity($pdo,'Atualizou configuração','4G','Configuração do 4G atualizada.',currentUserId());header('Location: '.appUrl('/4g/index.php?user='.$uid.'&saved=1'));exit;}
  $error='Não foi possível salvar a configuração.'; $c=array_merge($c,$d);
}
function h4i($v){return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configurações 4G</title><link rel="stylesheet" href="<?=h4i(appUrl('/assets/css/style.css'))?>"><style>.grid4{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.full4{grid-column:1/-1}@media(max-width:768px){.grid4{grid-template-columns:1fr}.full4{grid-column:auto}}</style></head><body><div class="dashboard"><?php require __DIR__.'/../includes/menu.php';?><main class="main-content"><?php require __DIR__.'/../includes/header.php';?><h1>Configurações <span>4G</span></h1><?php if(!empty($_GET['saved'])):?><div class="success">Configuração 4G salva.</div><?php endif;?><?php if(!empty($error)):?><div class="error"><?=h4i($error)?></div><?php endif;?><form method="post"><input type="hidden" name="user_id" value="<?=h4i($uid)?>"><div class="grid4">
<?php foreach(['version'=>'Version','app_name'=>'AppName','update_url'=>'UrlUpdate','sms_url'=>'Sms','logoonline'=>'logoonline','fundoonline'=>'fundoonline','logonline'=>'logonline','rodapeonline'=>'rodapeonline','email_feedback'=>'EmailFeedback','contato'=>'UrlContato','termos'=>'UrlTermos','udp_ports'=>'UdpPort'] as $k=>$label):?><div><label><?=h4i($label)?></label><input name="<?=h4i($k)?>" value="<?=h4i($c[$k]??'')?>"></div><?php endforeach;?><div><label>CheckUser</label><select name="check_user"><option value="true" <?=($c['check_user']??'true')==='true'?'selected':''?>>true</option><option value="false" <?=($c['check_user']??'')==='false'?'selected':''?>>false</option></select></div><div><label>EspessuraBordaCampo</label><input type="number" name="espessura_borda_campo" value="<?=h4i($c['espessura_borda_campo']??0)?>"></div><div class="full4"><label>ReleaseNotes</label><textarea name="release_notes" rows="3"><?=h4i($c['release_notes']??'')?></textarea></div>
<?php foreach($colors as $k=>$label):?><div><label><?=h4i($label)?></label><input name="<?=h4i($k)?>" value="<?=h4i($c[$k]??'')?>"></div><?php endforeach;?></div><div style="margin-top:18px"><button class="btn btn-save" type="submit">Salvar configuração 4G</button> <a class="btn btn-secondary" href="<?=h4i(appUrl('/4g/json.php?user='.$uid))?>">Config.json</a> <a class="btn" href="<?=h4i(appUrl('/4g/servers.php?user='.$uid))?>">Servidores</a> <a class="btn" href="<?=h4i(appUrl('/4g/networks.php?user='.$uid))?>">Networks</a></div></form></main></div></body></html>
